#!/usr/bin/env python3
"""Generate AOT adapters from the same configuration descriptions used by JIT."""
import argparse
from pathlib import Path
import re
import runpy

ROOT = Path(__file__).resolve().parents[1]
metadata = runpy.run_path(str(ROOT / 'python/mxfp6/_mxfp8_config.py'))


def generate(source, registry):
    manifest = metadata['load_manifest'](source)
    # These are the generated byproducts declared by CMake. Reject an incomplete
    # manifest rather than silently leaving a stale adapter in an incremental build.
    expected = {name: name for name in (
        'vector_store', 'specialized', 'cache_hint', 'occupancy', 'eightwarp')}
    expected['cute'] = 'cute_4warp'
    if {f['name']: f['header'] for f in manifest['families']} != expected:
        raise ValueError('Manifest must describe exactly the six migrated family headers')
    ranges = {name: (int(first), int(count)) for name, first, count in re.findall(
        r'MXFP8_FAMILY\((\w+),\s*(\d+),\s*(\d+),', registry.read_text())}
    outputs = {}
    configs = list(metadata['configurations'](manifest))
    for family in manifest['families']:
        name = family['name']
        if ranges.get(name) != (family['first_tactic'], len(family['configs'])):
            raise ValueError(f'{name}: configuration range disagrees with native registry')
        specialized = family['fixed_k'] != [0]
        args = 'C::bm, C::bn, C::bk, C::stages, C::swap'
        if specialized:
            args += ', FixedK, C::warp_m, C::packed_sf'
        lines = [
            '// Generated by generate_mxfp8_configs.py; edit mxfp8_cp_async.json.',
            '#pragma once', '#include "mxfp8_gemm/launch.cuh"',
            f'#include "mxfp8_gemm/kernels/{family["header"]}.cuh"',
            f'namespace mxfp8_{name} {{',
            'struct Kernel {',
            f'  static constexpr bool specialize_k = {str(specialized).lower()};',
            '  template<class C, int FixedK> static auto get() {',
            f'    return gemm<{args}>;', '  }', '};',
            'void mm_out(at::Tensor const& a, at::Tensor const& b, at::Tensor const& sa,',
            '            at::Tensor const& sb, at::Tensor const& out, int64_t config) {',
            '  mxfp8_common::validate(a, b, sa, sb, out);',
            '  c10::cuda::CUDAGuard guard(a.device());',
            '  switch (config) {',
        ]
        for c in configs:
            if c['family'] != name:
                continue
            values = ', '.join(str(c[k]).lower() for k in (
                'bm', 'bn', 'bk', 'stages', 'swap', 'warp_m', 'packed_sf', 'threads', 'shared_bytes'))
            lines.extend([f'    case {c["id"]}:',
                f'      mxfp8_host::dispatch<Kernel, mxfp8_host::Config<{values}>>',
                '          (a, b, sa, sb, out); break;'])
        message = 'Unknown four-warp configuration' if name == 'cute' else 'Unknown specialized configuration'
        lines.extend([f'    default: TORCH_CHECK(false, "{message}");', '  }', '}', '}'])
        outputs[family['header'] + '.cuh'] = '\n'.join(lines) + '\n'
    return outputs


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', type=Path, default=ROOT/'python/mxfp6/mxfp8_cp_async.json')
    parser.add_argument('--registry', type=Path, default=ROOT/'csrc/include/mxfp8_gemm/registry.def')
    parser.add_argument('--output-dir', type=Path, required=True)
    args = parser.parse_args()
    for name, source in generate(args.source, args.registry).items():
        path = args.output_dir/name
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists() or path.read_text() != source:
            path.write_text(source)


if __name__ == '__main__':
    main()
